head.script:
// 테스트 설명, 유효성 값 설정
//  ★ mergeClear : 동적으로 병합된 Body Cell 을 모두 원래 상태로 해제 (파라미터 없음).
//     · 본 샘플(_3)은 @spec3 중 '속성값(mergeCol 속성 + mergeExcludeValue 속성) 기반 제외조건 미초기화' 만 분리 시연한다.
//       (메소드 mergeCol()/mergeRow() 기반 제외조건 미초기화는 _2 샘플에서 다룬다.)
//     · ① 그리드 생성 시 속성(mergeCol='col2,col4' · mergeExcludeValue='X')으로 제외조건을 설정 + 자동병합 → ② mergeClear 실행 후
//       속성값 제외조건이 초기화되지 않고 그대로 유지되는지를 '재병합 시 제외 컬럼/값이 여전히 미병합되는지'로 확인한다.
//     · 내부 객체(mergeColObj 등) 직접 접근 금지 → 공개 옵션 options.mergeCol·options.mergeExcludeValue +
//       공개 API getMerged(row,col)·DOM(td rowSpan/colSpan) 으로만 기능적으로 관찰한다.
//     · @related(mergeCells)는 제외조건 setUp 용도로만 사용(검증 대상 아님).
scwin.tData = {
    "description" : "[gridView > M > mergeClear]<br/>동적으로 병합된 Body Cell 을 모두 원래 상태로 해제합니다.",
    "validation" : [
        "mergeCol, mergeExcludeValue 속성값으로 설정한 병합 제외 조건은 초기화되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 속성값 기반 제외조건이 드러나도록 구성.
//
//  행 | col1 | col2 | col3 | col4
//  ---+------+------+------+------
//   0 |  A   |  X   |  P   |  S
//   1 |  A   |  X   |  P   |  S
//   2 |  A   |  Y   |  P   |  S
//   3 |  A   |  Y   |  P   |  S
//
//  · mergeCol 속성 = 'col2,col4' : col2·col4 만 병합 대상(포함), 미지정 col1·col3 은 자동 제외.
//  · mergeExcludeValue 속성 = 'X'  : 값 X 셀(col2 행0~1) 자동병합 제외.
//  · mergeCells('bycol') 자동병합 결과 :
//      - col1(A,A,A,A) : 동일값이나 mergeCol 미지정 → 미병합  [제외]
//      - col2(X,X,Y,Y) : 값 X(행0~1) 제외 / 값 Y(행2~3) 만 병합  [부분]
//      - col3(P,P,P,P) : 동일값이나 mergeCol 미지정 → 미병합  [제외]
//      - col4(S,S,S,S) : mergeCol 지정 + 제외값 아님 → 행0~3 병합  [대조군]
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "X", "col3": "P", "col4": "S" },
    { "col1": "A", "col2": "X", "col3": "P", "col4": "S" },
    { "col1": "A", "col2": "Y", "col3": "P", "col4": "S" },
    { "col1": "A", "col2": "Y", "col3": "P", "col4": "S" }
];



// comp 생성 : mergeCol='col2,col4' + mergeExcludeValue='X' 속성을 부여한 그리드 1개를 동적 생성.
//  ★ mergeCells 류 속성은 attribute 로 주지 않는다 (초기 미병합 상태로 생성 → 버튼으로 병합/해제).
//     mergeCol·mergeExcludeValue 는 속성값 제외조건 유지(@spec3) 입증을 위해 생성 시 속성으로 부여한다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="속성 mergeCol=col2,col4 / mergeExcludeValue=X. ① 자동병합 → ② mergeClear 실행 후 속성값 제외조건이 초기화되지 않고 그대로 유지되는지 확인(@spec3 속성값 제외조건 미초기화)"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // mergeCol='col2,col4' (병합 대상 컬럼 화이트리스트) + mergeExcludeValue='X' (제외 값)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        mergeCol: "col2,col4",
        mergeExcludeValue: "X",
        defaultCellHeight: 34
    });

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:380px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeClear sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// ① 속성기반 자동병합 : 속성(mergeCol/mergeExcludeValue)은 생성 시 부여됨 → mergeCells('bycol') 자동병합만 실행.
scwin.btn_setUp_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // 자동 병합 (bycol) : 속성 mergeCol(col2,col4)·mergeExcludeValue(X) 기준으로 병합.
    target1.mergeCells("bycol");

    scwin.setUpDone = true;

    // ① 속성기반 자동병합 후 병합 영역 목록 출력.
    scwin.printMergeState(bottom);
}



// ② mergeClear 실행 후 재병합 : 모든 동적 병합을 해제(파라미터 없음)한 뒤 mergeCells('bycol')로 재병합.
//  @spec3 — 병합은 해제되지만 속성값(mergeCol/mergeExcludeValue) 제외조건은 초기화되지 않고 그대로 유지됨.
//  내부 객체 미사용 → 재병합 후 제외 컬럼/값 셀이 여전히 미병합인지를
//  공개 API getMerged(row,col) + DOM(td rowSpan/colSpan) + 공개 옵션 options.mergeCol·options.mergeExcludeValue 로 관찰하여 유지를 입증한다.
scwin.btn_mergeClear_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    if (!scwin.setUpDone) {
        bottom.setReturnValue("먼저 [① 속성기반 자동병합] 버튼을 눌러주세요.");
        return;
    }

    // mergeClear → 재병합 (속성값 제외조건 유지 여부를 기능적으로 관찰하기 위함)
    target1.mergeClear();

    target1.mergeCells("bycol");

    let gid = target1.id;

    // 특정 (row,col) 셀이 병합되었는지 여부 : 공개 API getMerged 를 1차, DOM(td rowSpan/colSpan)을 보조로 관찰.
    //  · 미병합 셀 → getMerged=false 이고 자기 td 의 rowSpan/colSpan 이 1.
    //  · 셀 td 는 id 규칙 {gridId}_cell_{row}_{col} 로 찾는다(data-rowindex 속성은 갱신되지 않음).
    let isMerged = function (row, col) {
        if (target1.getMerged(row, col)) {
            return true;
        }
        // DOM 보조 확인 : 해당 셀 td 의 rowSpan/colSpan 이 1 보다 크면 병합 시작셀.
        let td = document.getElementById(gid + "_cell_" + row + "_" + col);
        if (td && (td.rowSpan > 1 || td.colSpan > 1)) {
            return true;
        }
        return false;
    };

    // [대조군] col4(인덱스3) : mergeCol 지정 + 제외값 아님. col4 는 전부 동일값(S) → 재병합 시 병합되어야 정상.
    //   → 재병합 자체가 작동함을 보이는 대조군. (이게 병합돼야 아래 '제외 컬럼/값 미병합'이 '전부 해제'가 아닌 '제외 유지' 임이 성립)
    let col4Merged = isMerged(0, 3) || isMerged(1, 3) || isMerged(2, 3) || isMerged(3, 3);

    // col1(인덱스0) : mergeCol 속성 미지정 제외. col1 전부 동일값(A) → 제외 없으면 병합됐어야 하나 미병합이면 유지.
    let col1Merged = isMerged(0, 0) || isMerged(1, 0) || isMerged(2, 0) || isMerged(3, 0);

    // col3(인덱스2) : mergeCol 속성 미지정 제외. col3 전부 동일값(P) → 제외 없으면 병합됐어야 하나 미병합이면 유지.
    let col3Merged = isMerged(0, 2) || isMerged(1, 2) || isMerged(2, 2) || isMerged(3, 2);

    // 값 X(col2 인덱스1, 행0~1) : mergeExcludeValue='X' 제외. 값 X 동일값이나 제외 → 미병합이면 유지.
    let valXMerged = isMerged(0, 1) || isMerged(1, 1);

    // 공개 옵션 유지 확인
    let optMergeCol = target1.options.mergeCol;
    let optExcVal = target1.options.mergeExcludeValue;

    let keep = (!col1Merged && !col3Merged && !valXMerged && optMergeCol === "col2,col4" && optExcVal === "X");

    // ② mergeClear 후 재병합한 병합 영역 목록 출력.
    scwin.printMergeState(bottom);

    // 속성값(mergeCol/mergeExcludeValue) 제외조건 유지 결론 1줄.
    bottom.setReturnValue("→ mergeClear 후 재병합 : 대조 col4 " + (col4Merged ? "병합" : "미병합") + ", 제외 col1·col3·값X 미병합 → mergeCol/mergeExcludeValue 속성값 제외조건 " + (keep ? "유지됨" : "초기화됨"));
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로/가로/블록 병합 그룹을 출력.
//  td 셀렉터는 gid = target1.id 사용 (e.target.id 는 버튼 id 라 사용 불가).
//  표시 td 만(seen 키 + display/offset 가드) 집계하여 흡수된 숨김 셀 중복을 제거한다.
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let mergedCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        if (td.offsetWidth === 0) continue;

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            mergedCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("[행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    bottom.setReturnValue("[병합 상태] 병합 그룹 " + mergedCnt + "개 (0개 = 전체 해제)");
    for (let d = 0; d < descs.length; d++) bottom.setReturnValue("  - " + descs[d]);
}
